export const TypeSpecificValueInput: React.FC<{
  dataType: string;
  value: string;
  onChange: (val: string) => void;
  options?: string[];
  label?: string;
  helperText?: string;
  placeholder?: string;
}> = ({
  dataType = 'Text String',
  value,
  onChange,
  options = [],
  label = 'Default / Fallback Value',
  helperText = 'Fallback value when empty in lead records or call sessions.',
  placeholder
}) => {
  const norm = dataType.toLowerCase();

  // Boolean type
  if (norm.includes('bool')) {
    const isTrue = value === 'true' || value === 'yes' || value === '1';
    const isFalse = value === 'false' || value === 'no' || value === '0';
    return (
      <div className="space-y-1">
        <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
          {label}
        </label>
        <div className="grid grid-cols-2 gap-2 h-9">
          <button
            type="button"
            onClick={() => onChange('true')}
            className={`px-3 h-full rounded-lg text-xs font-semibold border flex items-center justify-center gap-1.5 transition-all cursor-pointer ${
              isTrue
                ? 'bg-emerald-600 text-white border-emerald-600 shadow-xs font-bold'
                : 'bg-white dark:bg-zinc-900 text-zinc-700 dark:text-zinc-300 border-zinc-200 dark:border-zinc-700 hover:bg-zinc-50'
            }`}
          >
            <span>✓</span> True / Yes
          </button>
          <button
            type="button"
            onClick={() => onChange('false')}
            className={`px-3 h-full rounded-lg text-xs font-semibold border flex items-center justify-center gap-1.5 transition-all cursor-pointer ${
              isFalse
                ? 'bg-rose-600 text-white border-rose-600 shadow-xs font-bold'
                : 'bg-white dark:bg-zinc-900 text-zinc-700 dark:text-zinc-300 border-zinc-200 dark:border-zinc-700 hover:bg-zinc-50'
            }`}
          >
            <span>✕</span> False / No
          </button>
        </div>
        {helperText && <p className="text-[10px] text-zinc-400 truncate">{helperText}</p>}
      </div>
    );
  }

  // Date type (YYYY-MM-DD)
  if (norm.includes('date') && !norm.includes('datetime') && !norm.includes('timestamp')) {
    return (
      <div className="space-y-1">
        <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
          {label}
        </label>
        <input
          type="date"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="w-full h-9 px-3 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono focus:outline-hidden focus:border-amber-500 cursor-pointer"
        />
        {helperText && <p className="text-[10px] text-zinc-400 truncate">{helperText}</p>}
      </div>
    );
  }

  // DateTime type (Timestamp)
  if (norm.includes('datetime') || norm.includes('timestamp')) {
    return (
      <div className="space-y-1">
        <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
          {label}
        </label>
        <input
          type="datetime-local"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="w-full h-9 px-3 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono focus:outline-hidden focus:border-amber-500 cursor-pointer"
        />
        {helperText && <p className="text-[10px] text-zinc-400 truncate">{helperText}</p>}
      </div>
    );
  }

  // Number type
  if (norm.includes('number')) {
    return (
      <div className="space-y-1">
        <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
          {label}
        </label>
        <input
          type="number"
          step="any"
          placeholder={placeholder || 'e.g. 50'}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="w-full h-9 px-3 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono focus:outline-hidden focus:border-amber-500"
        />
        {helperText && <p className="text-[10px] text-zinc-400 truncate">{helperText}</p>}
      </div>
    );
  }

  // Phone Number type
  if (norm.includes('phone')) {
    return (
      <div className="space-y-1">
        <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
          {label}
        </label>
        <div className="relative">
          <span className="absolute left-2.5 top-2.5 text-zinc-400 font-mono text-xs">📞</span>
          <input
            type="tel"
            placeholder={placeholder || 'e.g. +91 98765 43210'}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            className="w-full h-9 pl-8 pr-3 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono focus:outline-hidden focus:border-amber-500"
          />
        </div>
        {helperText && <p className="text-[10px] text-zinc-400 truncate">{helperText}</p>}
      </div>
    );
  }

  // Email Address type
  if (norm.includes('email')) {
    return (
      <div className="space-y-1">
        <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
          {label}
        </label>
        <div className="relative">
          <span className="absolute left-2.5 top-2.5 text-zinc-400 font-mono text-xs">✉️</span>
          <input
            type="email"
            placeholder={placeholder || 'e.g. name@example.com'}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            className="w-full h-9 pl-8 pr-3 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono focus:outline-hidden focus:border-amber-500"
          />
        </div>
        {helperText && <p className="text-[10px] text-zinc-400 truncate">{helperText}</p>}
      </div>
    );
  }

  // Currency / Monetary Value type
  if (norm.includes('currency') || norm.includes('amount')) {
    return (
      <div className="space-y-1">
        <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
          {label}
        </label>
        <div className="relative">
          <span className="absolute left-2.5 top-2.5 text-zinc-400 font-mono text-xs font-bold">$</span>
          <input
            type="number"
            step="0.01"
            placeholder={placeholder || 'e.g. 99.99'}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            className="w-full h-9 pl-7 pr-3 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono focus:outline-hidden focus:border-amber-500"
          />
        </div>
        {helperText && <p className="text-[10px] text-zinc-400 truncate">{helperText}</p>}
      </div>
    );
  }

  // JSON Object type
  if (norm.includes('json')) {
    return (
      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
            {label}
          </label>
          <div className="flex items-center gap-1">
            <button
              type="button"
              onClick={() => onChange('{"status": "active", "tier": "gold"}')}
              className="text-[10px] px-1.5 py-0.2 rounded bg-amber-100 dark:bg-amber-900/60 text-amber-800 dark:text-amber-200 font-mono hover:bg-amber-200 cursor-pointer"
            >
              + Sample
            </button>
            <button
              type="button"
              onClick={() => onChange('{}')}
              className="text-[10px] px-1.5 py-0.2 rounded bg-zinc-100 dark:bg-zinc-800 text-zinc-600 dark:text-zinc-400 font-mono hover:bg-zinc-200 cursor-pointer"
            >
              &#123;&#125;
            </button>
          </div>
        </div>
        <input
          type="text"
          placeholder={placeholder || 'e.g. {"status": "active", "tier": "gold"}'}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="w-full h-9 px-3 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono focus:outline-hidden focus:border-amber-500"
        />
        {helperText && <p className="text-[10px] text-zinc-400 truncate">{helperText}</p>}
      </div>
    );
  }

  // Secret Token type
  if (norm.includes('secret')) {
    return (
      <div className="space-y-1">
        <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
          {label}
        </label>
        <div className="relative">
          <span className="absolute left-2.5 top-2.5 text-zinc-400 font-mono text-xs">🔒</span>
          <input
            type="password"
            placeholder={placeholder || 'e.g. sk_test_secret_token'}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            className="w-full h-9 pl-8 pr-3 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono focus:outline-hidden focus:border-amber-500"
          />

        </div>
        {helperText && <p className="text-[10px] text-zinc-400 truncate">{helperText}</p>}
      </div>
    );
  }

  // Default String / Custom
  return (
    <div className="space-y-1">
      <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
        {label}
      </label>
      <input
        type="text"
        placeholder={placeholder || 'e.g. Delta Dental / General Patient'}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="w-full h-9 px-3 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 focus:outline-hidden focus:border-amber-500"
      />
      {helperText && <p className="text-[10px] text-zinc-400 truncate">{helperText}</p>}
    </div>
  );
};

interface VariableComboboxInputProps {
  value: string;
  onChange: (val: string) => void;
  options: string[];
  onOptionsChange: (newOptions: string[]) => void;
  dataType?: string;
  placeholder?: string;
  label?: string;
  helperText?: string;
}

const getPresetsForDataType = (type: string = 'String'): { label: string; value: string; desc?: string; badge?: string }[] => {
  const norm = type.toLowerCase();
  
  if (norm.includes('datetime') || norm.includes('timestamp')) {
    const now = new Date();
    const pad = (n: number) => n.toString().padStart(2, '0');
    const isoNow = now.toISOString();
    const localNow = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}T${pad(now.getHours())}:${pad(now.getMinutes())}`;
    
    const tomorrow = new Date(now.getTime() + 24 * 3600 * 1000);
    const tomorrow9am = `${tomorrow.getFullYear()}-${pad(tomorrow.getMonth() + 1)}-${pad(tomorrow.getDate())}T09:00:00`;
    const tomorrow2pm = `${tomorrow.getFullYear()}-${pad(tomorrow.getMonth() + 1)}-${pad(tomorrow.getDate())}T14:00:00`;

    const in2Days = new Date(now.getTime() + 2 * 24 * 3600 * 1000);
    const in2Days10am = `${in2Days.getFullYear()}-${pad(in2Days.getMonth() + 1)}-${pad(in2Days.getDate())}T10:00:00`;

    const nextWeek = new Date(now.getTime() + 7 * 24 * 3600 * 1000);
    const nextWeek10am = `${nextWeek.getFullYear()}-${pad(nextWeek.getMonth() + 1)}-${pad(nextWeek.getDate())}T10:00:00`;

    return [
      { label: 'Current Timestamp (Now)', value: isoNow, desc: 'ISO 8601 UTC string', badge: 'Live Now' },
      { label: 'Dynamic Real-time Tag', value: '{{now}}', desc: 'Resolved live on active call', badge: 'Dynamic' },
      { label: 'Tomorrow Morning (09:00 AM)', value: tomorrow9am, desc: 'Next business morning', badge: 'Calendar' },
      { label: 'Tomorrow Afternoon (02:00 PM)', value: tomorrow2pm, desc: 'Next business afternoon', badge: 'Calendar' },
      { label: 'In 2 Days (10:00 AM)', value: in2Days10am, desc: 'Follow-up appointment slot', badge: 'Slot' },
      { label: 'In 1 Week (10:00 AM)', value: nextWeek10am, desc: 'Weekly review appointment', badge: 'Slot' },
      { label: 'Local Current Time', value: localNow, desc: 'Client local timezone timestamp', badge: 'Local' },
      { label: 'Dynamic Lead Appointment', value: '{{appointment_datetime}}', desc: 'Lead calendar slot parameter', badge: 'Dynamic' }
    ];
  }

  if (norm.includes('date')) {
    const now = new Date();
    const pad = (n: number) => n.toString().padStart(2, '0');
    const today = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
    
    const tomorrow = new Date(now.getTime() + 24 * 3600 * 1000);
    const tomStr = `${tomorrow.getFullYear()}-${pad(tomorrow.getMonth() + 1)}-${pad(tomorrow.getDate())}`;

    const nextWeek = new Date(now.getTime() + 7 * 24 * 3600 * 1000);
    const nextWeekStr = `${nextWeek.getFullYear()}-${pad(nextWeek.getMonth() + 1)}-${pad(nextWeek.getDate())}`;

    const nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    const nextMonthStr = `${nextMonth.getFullYear()}-${pad(nextMonth.getMonth() + 1)}-01`;

    return [
      { label: 'Today (Current Date)', value: today, desc: 'YYYY-MM-DD standard date', badge: 'Today' },
      { label: 'Tomorrow', value: tomStr, desc: 'Next day standard date', badge: 'Tomorrow' },
      { label: 'Next Week', value: nextWeekStr, desc: '7 days from current date', badge: '7 Days' },
      { label: '1st of Next Month', value: nextMonthStr, desc: 'Start of next billing cycle', badge: 'Cycle' },
      { label: 'Dynamic Today Tag', value: '{{today}}', desc: 'Resolved dynamically at runtime', badge: 'Dynamic' },
      { label: 'Dynamic Scheduled Date', value: '{{scheduled_date}}', desc: 'Campaign dispatch date tag', badge: 'Dynamic' }
    ];
  }

  if (norm.includes('bool')) {
    return [
      { label: 'True (Active / Yes)', value: 'true', desc: 'Standard boolean true condition', badge: 'Boolean' },
      { label: 'False (Inactive / No)', value: 'false', desc: 'Standard boolean false condition', badge: 'Boolean' },
      { label: 'Yes (Textual)', value: 'yes', desc: 'Affirmative response format', badge: 'String' },
      { label: 'No (Textual)', value: 'no', desc: 'Negative response format', badge: 'String' },
      { label: '1 (Numeric Binary True)', value: '1', desc: 'Binary flag enabled', badge: 'Binary' },
      { label: '0 (Numeric Binary False)', value: '0', desc: 'Binary flag disabled', badge: 'Binary' }
    ];
  }

  if (norm.includes('number')) {
    return [
      { label: '0 (Default Zero)', value: '0', desc: 'Zero initial count', badge: 'Int' },
      { label: '1 (Single Unit / Attempt)', value: '1', desc: 'Initial retry or unit count', badge: 'Int' },
      { label: '3 (Max Retries)', value: '3', desc: 'Standard call retry limit', badge: 'Limit' },
      { label: '10 (Standard Batch Size)', value: '10', desc: 'Batch size threshold', badge: 'Int' },
      { label: '50 (Default Score)', value: '50', desc: 'Medium priority / lead score', badge: 'Score' },
      { label: '100 (Max Score / 100%)', value: '100', desc: 'Full quota or 100% threshold', badge: 'Max' },
      { label: '500 (Credits / Limit)', value: '500', desc: 'Mid-tier wallet / credit balance', badge: 'Balance' },
      { label: '99.99 (Standard Pricing)', value: '99.99', desc: 'Base subscription price point', badge: 'Currency' },
      { label: '1000 (Max Capacity)', value: '1000', desc: 'High limit threshold', badge: 'Capacity' }
    ];
  }

  if (norm.includes('secret')) {
    return [
      { label: 'Standard Bearer Token', value: 'Bearer sk_test_nexus_auth_token', desc: 'Authorization header format', badge: 'Auth' },
      { label: 'Stripe Secret Key Format', value: 'sk_test_51M0000000000000000000000', desc: 'Test payments secret', badge: 'API' },
      { label: 'API Key Masked Holder', value: 'nexus_api_key_xxxxxxxxxxxxxxxx', desc: 'Masked provider key', badge: 'Secret' },
      { label: 'Webhook HMAC Secret', value: 'whsec_secret_signing_key_hex', desc: 'Payload signature key', badge: 'HMAC' }
    ];
  }


  if (norm.includes('json')) {
    return [
      { label: 'Standard Status Object', value: '{"status": "active", "tier": "enterprise"}', desc: 'Key-value config payload', badge: 'JSON' },
      { label: 'Call Control Config', value: '{"max_duration_sec": 300, "recording": true, "language": "en"}', desc: 'Call parameters config', badge: 'Config' },
      { label: 'Webhook Dispatch Payload', value: '{"event": "appointment.confirmed", "notify_sms": true}', desc: 'Event notification payload', badge: 'Event' },
      { label: 'Empty JSON Object', value: '{}', desc: 'Minimal empty dictionary', badge: 'Empty' },
      { label: 'Empty JSON Array', value: '[]', desc: 'Minimal empty list', badge: 'Array' }
    ];
  }

  // String / Default
  return [
    { label: 'Youtube Channel Link', value: 'https://www.youtube.com/@Careersupport1', desc: 'Video & Social Channel', badge: 'URL' },
    { label: 'Official Website Link', value: 'https://careersupport1.com/', desc: 'Main domain landing URL', badge: 'URL' },
    { label: 'Customer Support Email', value: 'official@careersupport1.com', desc: 'Customer support mailbox', badge: 'Email' },
    { label: 'Helpdesk Phone Number', value: '+91 98765 43210', desc: 'Inbound hotline number', badge: 'Phone' },
    { label: 'Lead Priority: High', value: 'High Priority', desc: 'Urgent lead routing tag', badge: 'Tier' },
    { label: 'Account Tier: Enterprise', value: 'Enterprise Tier', desc: 'Premium client status', badge: 'Tier' },
    { label: 'Appointment Status: Confirmed', value: 'Confirmed', desc: 'Booking confirmation flag', badge: 'Status' }
  ];
};

const VariableComboboxInput: React.FC<VariableComboboxInputProps> = ({
  value,
  onChange,
  options = [],
  onOptionsChange,
  dataType = 'String',
  placeholder = 'e.g. Default value',
  label = 'CSV Fallback Value',
  helperText = 'Used when field is empty in CSV'
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [newOption, setNewOption] = useState('');
  const [activeTab, setActiveTab] = useState<'all' | 'presets' | 'custom'>('all');
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const smartPresets = useMemo(() => getPresetsForDataType(dataType), [dataType]);

  const filteredOptions = options.filter(opt => !search || opt.toLowerCase().includes(search.toLowerCase()));
  const filteredPresets = smartPresets.filter(p => !search || p.label.toLowerCase().includes(search.toLowerCase()) || p.value.toLowerCase().includes(search.toLowerCase()) || (p.desc && p.desc.toLowerCase().includes(search.toLowerCase())));

  const handleAddOption = (optVal?: string) => {
    const clean = (optVal !== undefined ? optVal : newOption).trim();
    if (!clean) return;
    if (!options.includes(clean)) {
      const updated = [...options, clean];
      onOptionsChange(updated);
      onChange(clean);
    } else {
      onChange(clean);
    }
    setNewOption('');
    setSearch('');
  };

  const handleSelectPreset = (presetVal: string) => {
    onChange(presetVal);
    setIsOpen(false);
  };

  const handleRemoveOption = (optToRemove: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const updated = options.filter(o => o !== optToRemove);
    onOptionsChange(updated);
    if (value === optToRemove) {
      onChange(updated[0] || '');
    }
  };

  const isDateType = dataType.toLowerCase().includes('date') && !dataType.toLowerCase().includes('datetime') && !dataType.toLowerCase().includes('timestamp');
  const isDateTimeType = dataType.toLowerCase().includes('datetime') || dataType.toLowerCase().includes('timestamp');

  return (
    <div ref={containerRef} className="relative w-full space-y-1">
      <div className="flex items-center justify-between">
        <label className="block text-xs font-semibold text-zinc-700 dark:text-zinc-300">
          {label}
        </label>
        <div className="flex items-center gap-1.5">
          <span className="text-[9px] px-1.5 py-0.2 rounded font-mono font-bold bg-zinc-100 dark:bg-zinc-800 text-zinc-600 dark:text-zinc-400">
            {dataType}
          </span>
          {options.length > 0 && (
            <span className="text-[10px] text-blue-600 dark:text-blue-400 font-mono font-medium">
              {options.length} custom option{options.length !== 1 ? 's' : ''}
            </span>
          )}
        </div>
      </div>

      <div className="relative flex items-center">
        <input
          type="text"
          placeholder={placeholder}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onFocus={() => setIsOpen(true)}
          className="w-full px-3 py-2 pr-16 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono placeholder-zinc-400 focus:outline-hidden focus:border-blue-500"
        />
        <div className="absolute right-1 flex items-center gap-0.5">
          {/* Native picker helper button for Date and DateTime */}
          {isDateType && (
            <input
              type="date"
              tabIndex={-1}
              onChange={(e) => {
                if (e.target.value) {
                  onChange(e.target.value);
                }
              }}
              className="w-6 h-6 opacity-0 absolute right-7 cursor-pointer"
              title="Pick exact date"
            />
          )}
          {isDateTimeType && (
            <input
              type="datetime-local"
              tabIndex={-1}
              onChange={(e) => {
                if (e.target.value) {
                  onChange(e.target.value);
                }
              }}
              className="w-6 h-6 opacity-0 absolute right-7 cursor-pointer"
              title="Pick exact date & time"
            />
          )}
          {(isDateType || isDateTimeType) && (
            <button
              type="button"
              className="text-zinc-400 hover:text-blue-600 dark:hover:text-blue-400 p-1.5 transition-colors cursor-pointer"
              title="Open Calendar Date Picker"
            >
              <Calendar className="h-3.5 w-3.5" />
            </button>
          )}

          <button
            type="button"
            onClick={() => {
              setSearch('');
              setIsOpen(prev => !prev);
            }}
            className="text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-200 p-1.5 transition-colors cursor-pointer"
            title="Toggle options dropdown"
          >
            <ChevronDown className={`h-4 w-4 transition-transform duration-200 ${isOpen ? 'rotate-180 text-blue-500' : ''}`} />
          </button>
        </div>
      </div>

      <p className="text-[10px] text-zinc-400">{helperText}</p>

      {isOpen && (
        <div className="absolute z-50 left-0 right-0 mt-1 rounded-xl border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-100">
          {/* Specialized Quick-Add Bar based on Data Type */}
          {isDateType ? (
            <div className="p-2.5 border-b border-zinc-100 dark:border-zinc-800 bg-zinc-50/80 dark:bg-zinc-950/80">
              <div className="flex items-center gap-1.5">
                <div className="relative flex-1 min-w-0 flex items-center">
                  <Calendar className="h-3.5 w-3.5 text-blue-500 absolute left-2.5 pointer-events-none" />
                  <input
                    type="date"
                    value={newOption}
                    onChange={(e) => setNewOption(e.target.value)}
                    className="w-full h-8 pl-8 pr-2 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono focus:outline-none focus:ring-1 focus:ring-blue-500 cursor-pointer"
                  />
                </div>
                <button
                  type="button"
                  disabled={!newOption.trim()}
                  onClick={() => handleAddOption()}
                  className="h-8 px-3 rounded-lg bg-blue-600 hover:bg-blue-700 text-white text-xs font-semibold disabled:opacity-40 transition-colors flex items-center gap-1 shrink-0 cursor-pointer shadow-xs"
                >
                  <Plus className="h-3.5 w-3.5" />
                  <span>Add Date</span>
                </button>
              </div>
            </div>
          ) : isDateTimeType ? (
            <div className="p-2.5 border-b border-zinc-100 dark:border-zinc-800 bg-zinc-50/80 dark:bg-zinc-950/80">
              <div className="flex items-center gap-1.5">
                <div className="relative flex-1 min-w-0 flex items-center">
                  <Calendar className="h-3.5 w-3.5 text-blue-500 absolute left-2.5 pointer-events-none" />
                  <input
                    type="datetime-local"
                    value={newOption}
                    onChange={(e) => setNewOption(e.target.value)}
                    className="w-full h-8 pl-8 pr-1 text-xs rounded-lg border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 font-mono focus:outline-none focus:ring-1 focus:ring-blue-500 cursor-pointer"
                  />
                </div>
                <button
                  type="button"
                  disabled={!newOption.trim()}
                  onClick={() => handleAddOption()}
                  className="h-8 px-3 rounded-lg bg-blue-600 hover:bg-blue-700 text-white text-xs font-semibold disabled:opacity-40 transition-colors flex items-center gap-1 shrink-0 cursor-pointer shadow-xs"
                >
                  <Plus className="h-3.5 w-3.5" />
                  <span>Add</span>
                </button>
              </div>
            </div>
          ) : (
            <div className="p-2 border-b border-zinc-100 dark:border-zinc-800 bg-zinc-50/80 dark:bg-zinc-950/80 flex items-center gap-1.5">
              <input
                type={dataType.toLowerCase().includes('number') ? 'number' : 'text'}
                placeholder={`Type custom ${dataType} option and press Add...`}
                value={newOption}
                onChange={(e) => setNewOption(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    handleAddOption();
                  }
                }}
                className="flex-1 h-8 px-3 text-xs rounded-md border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-zinc-100 placeholder-zinc-400 focus:outline-none focus:ring-1 focus:ring-blue-500 font-mono"
              />
              <button
                type="button"
                disabled={!newOption.trim()}
                onClick={() => handleAddOption()}
                className="h-8 px-3 rounded-md bg-blue-600 hover:bg-blue-700 text-white text-xs font-semibold disabled:opacity-40 transition-colors flex items-center gap-1 shrink-0 cursor-pointer"
              >
                <Plus className="h-3.5 w-3.5" />
                <span>Add</span>
              </button>
            </div>
          )}

          {/* Search Bar & Category Filter Tabs */}
          <div className="p-2 border-b border-zinc-100 dark:border-zinc-800 bg-white dark:bg-zinc-900 space-y-1.5">
            <div className="relative flex items-center">
              <Search className="h-3.5 w-3.5 text-zinc-400 absolute left-2.5 pointer-events-none" />
              <input
                type="text"
                placeholder={`Search ${dataType} options & smart presets...`}
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full h-7 pl-8 pr-6 text-xs rounded-md border border-zinc-200 dark:border-zinc-700 bg-zinc-50 dark:bg-zinc-800 text-zinc-800 dark:text-zinc-200 placeholder-zinc-400 focus:outline-none focus:ring-1 focus:ring-blue-500"
              />
              {search && (
                <button
                  type="button"
                  onClick={() => setSearch('')}
                  className="absolute right-2 text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-200 cursor-pointer"
                >
                  <X className="h-3 w-3" />
                </button>
              )}
            </div>

            <div className="flex items-center gap-1">
              <button
                type="button"
                onClick={() => setActiveTab('all')}
                className={`px-2 py-0.5 rounded text-[10px] font-semibold transition-colors ${
                  activeTab === 'all'
                    ? 'bg-blue-100 dark:bg-blue-900 text-blue-700 dark:text-blue-200'
                    : 'text-zinc-500 hover:bg-zinc-100 dark:hover:bg-zinc-800'
                }`}
              >
                All ({filteredOptions.length + filteredPresets.length})
              </button>
              <button
                type="button"
                onClick={() => setActiveTab('presets')}
                className={`px-2 py-0.5 rounded text-[10px] font-semibold transition-colors flex items-center gap-1 ${
                  activeTab === 'presets'
                    ? 'bg-amber-100 dark:bg-amber-950 text-amber-700 dark:text-amber-300'
                    : 'text-zinc-500 hover:bg-zinc-100 dark:hover:bg-zinc-800'
                }`}
              >
                <span>💡 {dataType} Presets ({filteredPresets.length})</span>
              </button>
              {options.length > 0 && (
                <button
                  type="button"
                  onClick={() => setActiveTab('custom')}
                  className={`px-2 py-0.5 rounded text-[10px] font-semibold transition-colors ${
                    activeTab === 'custom'
                      ? 'bg-purple-100 dark:bg-purple-950 text-purple-700 dark:text-purple-300'
                      : 'text-zinc-500 hover:bg-zinc-100 dark:hover:bg-zinc-800'
                  }`}
                >
                  My Options ({filteredOptions.length})
                </button>
              )}
            </div>
          </div>

          <div className="max-h-56 overflow-y-auto p-1.5 space-y-2">
            {/* Custom Options Section */}
            {(activeTab === 'all' || activeTab === 'custom') && filteredOptions.length > 0 && (
              <div className="space-y-0.5">
                <div className="px-2 py-1 text-[9px] font-bold uppercase tracking-wider text-zinc-400 flex items-center justify-between">
                  <span>Custom Options ({filteredOptions.length})</span>
                  <span className="text-[8px] font-normal">Click to set fallback</span>
                </div>
                {filteredOptions.map((opt, idx) => {
                  const isSelected = value && value.trim() === opt.trim();
                  return (
                    <div
                      key={idx}
                      onClick={() => {
                        onChange(opt);
                        setIsOpen(false);
                      }}
                      className={`px-2.5 py-1.5 rounded-lg text-xs font-mono flex items-center justify-between cursor-pointer transition-colors ${
                        isSelected
                          ? 'bg-blue-50 dark:bg-blue-950/80 text-blue-700 dark:text-blue-300 font-bold border border-blue-200 dark:border-blue-800'
                          : 'hover:bg-zinc-100 dark:hover:bg-zinc-800 text-zinc-700 dark:text-zinc-300'
                      }`}
                    >
                      <span className="truncate pr-2">{opt}</span>
                      <div className="flex items-center gap-1.5 shrink-0">
                        {isSelected && (
                          <span className="text-[9px] font-sans font-semibold px-1.5 py-0.2 rounded bg-blue-600 text-white">
                            Active
                          </span>
                        )}
                        <button
                          type="button"
                          onClick={(e) => handleRemoveOption(opt, e)}
                          className="text-zinc-400 hover:text-red-500 p-0.5 rounded transition-colors"
                          title="Delete option"
                        >
                          <Trash2 className="h-3 w-3" />
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {/* Smart Presets Section */}
            {(activeTab === 'all' || activeTab === 'presets') && filteredPresets.length > 0 && (
              <div className="space-y-1">
                <div className="px-2 py-1 text-[9px] font-bold uppercase tracking-wider text-amber-600 dark:text-amber-400 flex items-center justify-between">
                  <span className="flex items-center gap-1">
                    <Sparkles className="h-3 w-3" />
                    <span>Recommended {dataType} Presets</span>
                  </span>
                  <span className="text-[8px] font-normal text-zinc-400">1-click assign &amp; save</span>
                </div>
                <div className="grid grid-cols-1 gap-1">
                  {filteredPresets.map((preset, pIdx) => {
                    const isSelected = value && value.trim() === preset.value.trim();
                    return (
                      <div
                        key={pIdx}
                        onClick={() => handleSelectPreset(preset.value)}
                        className={`p-2 rounded-lg border text-left cursor-pointer transition-all ${
                          isSelected
                            ? 'bg-amber-50 dark:bg-amber-950/70 border-amber-300 dark:border-amber-700 shadow-xs'
                            : 'bg-zinc-50/70 dark:bg-zinc-900/70 border-zinc-200/80 dark:border-zinc-800 hover:border-amber-300 dark:hover:border-amber-700 hover:bg-amber-50/40 dark:hover:bg-amber-950/40'
                        }`}
                      >
                        <div className="flex items-center justify-between gap-1.5 mb-0.5">
                          <span className="font-semibold text-xs text-zinc-900 dark:text-zinc-100 flex items-center gap-1">
                            <span>{preset.label}</span>
                            {preset.badge && (
                              <span className="text-[8px] font-sans font-bold px-1.5 py-0.2 rounded bg-amber-100 dark:bg-amber-900/60 text-amber-700 dark:text-amber-300">
                                {preset.badge}
                              </span>
                            )}
                          </span>
                          {isSelected && (
                            <span className="text-[9px] font-bold text-amber-600 dark:text-amber-400">
                              ✓ Selected
                            </span>
                          )}
                        </div>
                        <div className="text-[11px] font-mono text-zinc-600 dark:text-zinc-300 truncate">
                          {preset.value}
                        </div>
                        {preset.desc && (
                          <div className="text-[10px] text-zinc-400 mt-0.5">
                            {preset.desc}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {filteredOptions.length === 0 && filteredPresets.length === 0 && (
              <div className="p-4 text-center text-xs text-zinc-400 italic">
                No matching options or presets found for &quot;{search}&quot;.
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

