export const getDynamicWorkspaceTargets = (
  scope: string,
  workspaceAgents: any[] = [],
  workspaceCampaigns: any[] = [],
  customItems: Record<string, any[]> = {}
): { label: string; value: string; icon?: string; badge?: string }[] => {
  if (scope === 'Sidebar Modules') {
    return SIDEBAR_PROJECT_MODULES.map(m => ({
      value: m.name,
      label: `${m.icon} ${m.name}`,
      badge: m.category
    }));
  }

  if (scope === 'Agent Specific') {
    const list: string[] = [];
    (workspaceAgents || []).forEach(a => {
      const name = a.name || a.agent_name || a.title;
      if (name && !list.includes(name)) list.push(name);
    });

    try {
      ['nexus_agents', 'nexus_created_agents', 'nexus_voice_agents'].forEach(k => {
        const raw = localStorage.getItem(k);
        if (raw) {
          const parsed = JSON.parse(raw);
          const items = Array.isArray(parsed) ? parsed : parsed.items || [];
          items.forEach((a: any) => {
            const name = a.name || a.agent_name || a.title;
            if (name && !list.includes(name)) list.push(name);
          });
        }
      });
    } catch (e) {}

    MOCK_TARGET_AI_AGENTS.forEach(def => {
      if (!list.includes(def)) list.push(def);
    });

    return list.map(name => ({ value: name, label: `🤖 ${name}`, badge: 'AI Agent' }));
  }

  if (scope === 'Campaign Specific') {
    const list: string[] = [];
    (workspaceCampaigns || []).forEach(c => {
      const name = c.name || c.campaign_name || c.title;
      if (name && !list.includes(name)) list.push(name);
    });

    try {
      ['nexus_campaigns', 'nexus_outbound_campaigns'].forEach(k => {
        const raw = localStorage.getItem(k);
        if (raw) {
          const parsed = JSON.parse(raw);
          const items = Array.isArray(parsed) ? parsed : parsed.items || [];
          items.forEach((c: any) => {
            const name = c.name || c.campaign_name || c.title;
            if (name && !list.includes(name)) list.push(name);
          });
        }
      });
    } catch (e) {}

    MOCK_TARGET_CAMPAIGNS.forEach(def => {
      if (!list.includes(def)) list.push(def);
    });

    return list.map(name => ({ value: name, label: `📢 ${name}`, badge: 'Campaign' }));
  }

  if (scope === 'Phone Number Specific') {
    const list: string[] = [];
    try {
      ['nexus_phone_numbers', 'nexus_sip_trunks'].forEach(k => {
        const raw = localStorage.getItem(k);
        if (raw) {
          const parsed = JSON.parse(raw);
          const items = Array.isArray(parsed) ? parsed : parsed.items || [];
          items.forEach((p: any) => {
            const num = p.phone_number || p.number || p.name || p.did;
            if (num && !list.includes(num)) list.push(num);
          });
        }
      });
    } catch (e) {}

    MOCK_TARGET_PHONE_NUMBERS.forEach(def => {
      if (!list.includes(def)) list.push(def);
    });

    return list.map(num => ({ value: num, label: `📞 ${num}`, badge: 'Phone DID' }));
  }

  if (scope === 'Voice Workflow Specific') {
    const list: string[] = [];
    try {
      ['nexus_workflows', 'nexus_voice_workflows'].forEach(k => {
        const raw = localStorage.getItem(k);
        if (raw) {
          const parsed = JSON.parse(raw);
          const items = Array.isArray(parsed) ? parsed : parsed.items || [];
          items.forEach((w: any) => {
            const name = w.name || w.workflow_name || w.title;
            if (name && !list.includes(name)) list.push(name);
          });
        }
      });
    } catch (e) {}

    ['Inbound Reception IVR Flow', 'Appointment Scheduling Logic', 'Payment Collection Sequence', 'Emergency Triage Escalation'].forEach(def => {
      if (!list.includes(def)) list.push(def);
    });

    return list.map(name => ({ value: name, label: `⚡ ${name}`, badge: 'Workflow' }));
  }

  if (scope === 'Organization Level') {
    const list: string[] = [];
    const depts = customItems['departments'] || [];
    depts.forEach(d => {
      const name = d.display_name || d.name;
      if (name && !list.includes(name)) list.push(name);
    });

    MOCK_TARGET_DEPARTMENTS.forEach(def => {
      if (!list.includes(def)) list.push(def);
    });

    return list.map(name => ({ value: name, label: `🏢 ${name}`, badge: 'Department' }));
  }

  if (scope === 'Team / Role Specific') {
    return MOCK_TARGET_ROLES.map(role => ({ value: role, label: `👥 ${role}`, badge: 'Role / Team' }));
  }

  return [];
};

