  const handleAddVarOption = (val?: string) => {
    const toAdd = (val !== undefined ? val : varNewOptionInput).trim();
    if (!toAdd) return;
    const current = varAllowedValues ? varAllowedValues.split(/[,;\n]/).map((s) => s.trim()).filter(Boolean) : [];
    if (!current.includes(toAdd)) {
      const next = [...current, toAdd];
      setVarAllowedValues(next.join(', '));
    }
    setVarNewOptionInput('');
  };

  const handleRemoveVarOption = (valToRemove: string) => {
    const current = varAllowedValues ? varAllowedValues.split(/[,;\n]/).map((s) => s.trim()).filter(Boolean) : [];
    const next = current.filter((item) => item !== valToRemove);
    setVarAllowedValues(next.join(', '));
  };

