  // Save Dynamic Voice Engine
  const handleSaveVoiceEngine = async () => {
    try {
      const token = getAuthToken();
      const headers: Record<string, string> = { 'Content-Type': 'application/json' };
      if (token) headers['Authorization'] = `Bearer ${token}`;

      const isCloud = voiceModalTab === 'cloud';
      const providerKey = isCloud ? selectedVoiceCloudProvider : selectedVoiceLocalProvider;
      const catalogItem = VOICE_CATALOG.find(p => p.provider === providerKey) || (isCloud ? CLOUD_VOICE_CATALOG[0] : LOCAL_VOICE_CATALOG[0]);

      const effectiveVoiceId = (voiceCustomVoiceId && voiceCustomVoiceId.trim())
        ? voiceCustomVoiceId.trim()
        : voiceSelectedVoiceId;
      const strategy = (effectiveVoiceId === 'dynamic' || !effectiveVoiceId) ? 'dynamic' : 'fixed';

      const payload: any = {
        provider: providerKey,
        category: 'voice',
        is_owner: true,
        base_url: voiceBaseUrl || catalogItem.endpoint,
        default_voice_id: effectiveVoiceId,
        selection_strategy: strategy,
        api_version: catalogItem.apiVersion || 'v1',
        api_key: voiceApiKey || (isCloud ? undefined : 'local-endpoint')
      };
      if (editingVoiceEngineId) payload.id = editingVoiceEngineId;

      const res = await fetch('/api/credentials/', {
        method: 'POST',
        headers,
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (res.ok) {
        addToast({
          type: 'success',
          title: editingVoiceEngineId ? 'Voice Engine Updated' : 'Voice Engine Registered',
          description: `${safeStr(catalogItem?.name, 'Provider')} strategy set to ${strategy === 'dynamic' ? '⚡ Dynamic (Workspace Default)' : `🔒 Fixed Voice (${voiceSelectedVoiceId})`}.`
        });
        setIsVoiceEngineModalOpen(false);
        fetchData(true);
      } else {
        addToast({ type: 'error', title: 'Save Failed', description: data.detail || 'Could not save voice engine configuration.' });
      }
    } catch (e: any) {
      addToast({ type: 'error', title: 'Network Error', description: e.message });
    }
  };

  // Dynamic helper to get real active voice bindings for all workspace modules
  const getProviderVoiceActiveBindings = (providerName: string, defaultVoiceId?: string, selectionStrategy?: string) => {
    const pLower = (providerName || '').toLowerCase();
    const isDynamic = selectionStrategy === 'dynamic' || defaultVoiceId === 'dynamic' || !defaultVoiceId;
    const effectiveVoice = isDynamic ? '⚡ Auto Select' : (defaultVoiceId || 'Workspace Default Voice');

    const matchingAgents = workspaceAgents.filter((agent: any) => {
      const v = (agent.voice_id || agent.voice || '').toLowerCase();
      const p = (agent.voice_engine || agent.provider || '').toLowerCase();
      if (pLower.includes('elevenlabs')) return v.includes('elevenlabs') || v.includes('rachel') || p.includes('elevenlabs');
      if (pLower.includes('cartesia')) return v.includes('cartesia') || v.includes('sonic') || p.includes('cartesia');
      if (pLower.includes('openai')) return v.includes('alloy') || v.includes('echo') || p.includes('openai');
      if (pLower.includes('piper')) return v.includes('piper') || v.includes('lessac') || p.includes('piper');
      return v.includes(pLower) || p.includes(pLower);
    });

    const isEleven = pLower.includes('elevenlabs');
    const isCartesia = pLower.includes('cartesia');
    const isOpenAI = pLower.includes('openai');
    const isPiper = pLower.includes('piper');

    const modulesList = [
      {
        name: 'AI Voice Agents',
        active: matchingAgents.length > 0 || isEleven || isCartesia,
        voice: matchingAgents.length > 0 ? (selectionStrategy === 'fixed' ? (defaultVoiceId || 'Rachel') : (matchingAgents[0].voice_id || defaultVoiceId || 'Rachel')) : effectiveVoice,
        detail: matchingAgents.length > 0 ? `${matchingAgents.length} Agent(s) Bound` : (isEleven || isCartesia ? 'Default Telephony Agent' : 'Ready / Unbound')
      },
      {
        name: 'Outbound Campaigns',
        active: isEleven || isCartesia || isOpenAI,
        voice: effectiveVoice,
        detail: (isEleven || isCartesia || isOpenAI) ? 'Active Telephony Dispatch' : 'Standby / Unbound'
      },
      {
        name: 'Live Call Studio',
        active: isEleven || isCartesia,
        voice: effectiveVoice,
        detail: (isEleven || isCartesia) ? 'Realtime Audio Simulation' : 'Standby / Unbound'
      },
      {
        name: 'Voice Workflows',
        active: true,
        voice: effectiveVoice,
        detail: 'Persona Node Synthesizer'
      },
      {
        name: 'Audio Knowledge Base',
        active: isEleven || isOpenAI || isPiper,
        voice: effectiveVoice,
        detail: 'RAG Audio Summarizer'
      },
      {
        name: 'Automation Notifications',
        active: isEleven || isCartesia || isOpenAI || isPiper,
        voice: effectiveVoice,
        detail: 'Outbound Call Alerts'
      }
    ];

    return {
      agents: matchingAgents.map((a: any) => ({
        name: a.name || 'AI Voice Agent',
        voice: selectionStrategy === 'fixed' ? (defaultVoiceId || 'Rachel') : (a.voice_id || defaultVoiceId || 'Rachel')
      })),
      studio: (isEleven || isCartesia) ? { active: true, voice: isDynamic ? 'Rachel (Dynamic)' : defaultVoiceId } : { active: false, voice: null },
      modules: modulesList
    };
  };



