  // SemVer Version Bump Helpers for Prompt Templates
  const bumpSemverPatch = (v: string) => {
    const clean = (v || 'v1.0.0').replace(/^v/, '');
    const parts = clean.split('.').map(n => parseInt(n, 10) || 0);
    const major = parts[0] !== undefined ? parts[0] : 1;
    const minor = parts[1] !== undefined ? parts[1] : 0;
    const patch = (parts[2] !== undefined ? parts[2] : 0) + 1;
    return `v${major}.${minor}.${patch}`;
  };

  const bumpSemverMinor = (v: string) => {
    const clean = (v || 'v1.0.0').replace(/^v/, '');
    const parts = clean.split('.').map(n => parseInt(n, 10) || 0);
    const major = parts[0] !== undefined ? parts[0] : 1;
    const minor = (parts[1] !== undefined ? parts[1] : 0) + 1;
    return `v${major}.${minor}.0`;
  };

  const bumpSemverMajor = (v: string) => {
    const clean = (v || 'v1.0.0').replace(/^v/, '');
    const parts = clean.split('.').map(n => parseInt(n, 10) || 0);
    const major = (parts[0] !== undefined ? parts[0] : 1) + 1;
    return `v${major}.0.0`;
  };
