  const handlePromptJsonImport = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        if (!content) return;

        let parsed: any = null;
        try {
          parsed = JSON.parse(content);
        } catch (_) {
          // Treat as raw text system prompt if not JSON
          parsed = { system_prompt: content };
        }

        if (parsed.name || parsed.template_name) setPtName(parsed.name || parsed.template_name);
        if (parsed.display_name || parsed.title) setPtDisplayName(parsed.display_name || parsed.title);
        if (parsed.category) setPtCategory(parsed.category);
        if (parsed.version) setPtVersion(parsed.version);
        if (parsed.model || parsed.model_compatibility) setPtModelCompatibility(parsed.model || parsed.model_compatibility);
        if (parsed.system_prompt || parsed.prompt || parsed.instructions) setPtSystemPrompt(parsed.system_prompt || parsed.prompt || parsed.instructions);
        if (parsed.user_prompt || parsed.greeting || parsed.user_greeting) setPtUserPrompt(parsed.user_prompt || parsed.greeting || parsed.user_greeting);

        addToast({
          type: 'success',
          title: 'Prompt Configuration Imported',
          description: `Successfully parsed "${file.name}". All system prompt fields & variables auto-populated.`
        });
      } catch (err) {
        addToast({ type: 'error', title: 'Import Failed', description: 'Invalid JSON or text file format.' });
      }
    };
    reader.readAsText(file);
  };
  const [uploadedFileDetails, setUploadedFileDetails] = useState<{
    name: string;
    size: string;
    format: string;
    chunks: number;
    filePath?: string;
    content?: string;
  } | null>(null);

  const handlePhysicalFileUpload = async (file: File) => {
    if (!file) return;
    const ext = file.name.split('.').pop()?.toUpperCase() || 'TXT';
    const sizeStr = file.size > 1024 * 1024
      ? `${(file.size / (1024 * 1024)).toFixed(2)} MB`
      : `${(file.size / 1024).toFixed(1)} KB`;

    addToast({
      type: 'info',
      title: '📤 Uploading Document...',
      description: `Processing "${file.name}" (${sizeStr}) and indexing vector chunks...`
    });

    try {
      const formData = new FormData();
      formData.append('file', file);
      if (kcEmbeddingProvider) formData.append('provider', kcEmbeddingProvider);
      if (kcEmbeddingModel) formData.append('model', kcEmbeddingModel);

      const token = getAuthToken();
      const headers: Record<string, string> = {};
      if (token) headers['Authorization'] = `Bearer ${token}`;

      const res = await fetch('/api/knowledge-base/parse-document', {
        method: 'POST',
        headers,
        body: formData
      });

      if (res.ok) {
        const data = await res.json();
        const fileTextContent = data.text || '';
        const parsedFormat = data.format || ext;
        const estimatedChunks = data.chunk_count || Math.max(1, Math.round(file.size / 512));

        const details = {
          name: file.name,
          size: sizeStr,
          format: parsedFormat,
          chunks: estimatedChunks,
          content: fileTextContent
        };

        setUploadedFileDetails(details);
        setKcRawText(fileTextContent);
        setKcFileFormat(parsedFormat);
        if (!kcName) setKcName(file.name.replace(/\.[^/.]+$/, "").toLowerCase().replace(/[^a-z0-9_]/g, '_'));
        if (!kcDisplayName) setKcDisplayName(file.name.replace(/\.[^/.]+$/, ""));

        addToast({
          type: 'success',
          title: '✅ Document Uploaded & Processed',
          description: `"${file.name}" processed successfully (${data.page_count || 1} pages, ${estimatedChunks} chunks).`
        });
      } else {
        const errData = await res.json().catch(() => ({}));
        const errMsg = errData.detail || `Failed to parse document (HTTP ${res.status})`;
        setUploadedFileDetails(null);
        setKcRawText('');
        addToast({
          type: 'error',
          title: 'Document Parsing Failed',
          description: errMsg
        });
      }
    } catch (e: any) {
      console.error('Backend document parse error:', e);
      setUploadedFileDetails(null);
      setKcRawText('');
      addToast({
        type: 'error',
        title: 'Upload / Parse Error',
        description: e?.message || 'Could not connect to document parsing service.'
      });
    }
  };

