  const detectCarrierPreset = (item: any): CarrierPresetKey => {
    if (!item) return 'twilio';
    const str = `${item.preset_key || ''} ${item.name || ''} ${item.provider || ''} ${item.provider_type || ''} ${item.display_name || ''} ${item.description || ''} ${item.base_url || ''}`.toLowerCase();
    if (str.includes('smartflo') || str.includes('ttbs') || str.includes('tata')) return 'tata_smartflo';
    if (str.includes('airtel')) return 'airtel_iq';
    if (str.includes('jio')) return 'jio_enterprise';
    if (str.includes('myoperator')) return 'myoperator';
    if (str.includes('servetel')) return 'servetel';
    if (str.includes('exotel')) return 'exotel';
    if (str.includes('knowlarity')) return 'knowlarity';
    if (str.includes('plivo')) return 'plivo';
    if (str.includes('sinch')) return 'sinch';
    if (str.includes('vonage') || str.includes('nexmo')) return 'vonage';
    if (str.includes('bandwidth')) return 'bandwidth';
    if (str.includes('signalwire')) return 'signalwire';
    if (str.includes('chime') || str.includes('aws')) return 'aws_chime';
    if (str.includes('azure') || str.includes('acs')) return 'azure_acs';
    if (str.includes('commio') || str.includes('thinq')) return 'commio';
    if (str.includes('flowroute')) return 'flowroute';
    if (str.includes('freepbx') || str.includes('pbxact')) return 'freepbx';
    if (str.includes('asterisk') || str.includes('pjsip')) return 'asterisk';
    if (str.includes('cisco') || str.includes('cucm')) return 'cisco_cucm';
    if (str.includes('3cx') || str.includes('threecx')) return 'threecx';
    if (str.includes('kamailio')) return 'kamailio';
    if (str.includes('freeswitch')) return 'freeswitch';
    if (str.includes('dinstar') || str.includes('goip')) return 'dinstar_gsm';
    if (str.includes('dongle') || str.includes('usb')) return 'usb_modem';
    if (str.includes('esim')) return 'cloud_esim';
    if (str.includes('telnyx')) return 'telnyx';
    if (str.includes('gsm') || str.includes('android') || str.includes('sim')) return 'gsm';
    if (str.includes('custom_sip')) return 'custom_sip';
    if (str.includes('custom_webhook')) return 'custom_webhook';
    if (str.includes('custom')) return 'custom';
    return 'twilio';
  };

  // Helper functions for Dynamic Pricing Engine (Section D)
  const normalizePricingMode = (mode: string | undefined): 'Paid' | 'Free' | 'Free Trial' | 'Flat-Rate Unlimited' | 'Custom' => {
    if (!mode) return 'Paid';
    const m = String(mode).toLowerCase();
    if (m.includes('trial')) return 'Free Trial';
    if (m.includes('flat') || m.includes('unlimited')) return 'Flat-Rate Unlimited';
    if (m.includes('custom') || m.includes('tier') || m.includes('contract')) return 'Custom';
    if (m.includes('free') || m.includes('zero')) return 'Free';
    return 'Paid';
  };

  const getCurrencySymbolForCountry = (countryOrCurrency: string): string => {
    const s = String(countryOrCurrency || '').toLowerCase();
    if (s.includes('inr') || s.includes('india') || s.includes('+91') || s.includes('₹')) return '₹';
    if (s.includes('eur') || s.includes('europe') || s.includes('€')) return '€';
    if (s.includes('gbp') || s.includes('uk') || s.includes('united kingdom') || s.includes('£')) return '£';
    if (s.includes('jpy') || s.includes('japan') || s.includes('¥')) return '¥';
    return '$';
  };

