  const handlePricingModeChange = (newMode: string, customPreset?: CarrierPresetKey, customCountry?: string) => {
    const norm = normalizePricingMode(newMode);
    const currPresetKey = customPreset || carrierPreset;
    const preset = TELEPHONY_CARRIER_PRESETS[currPresetKey] || TELEPHONY_CARRIER_PRESETS.twilio;
    const sym = getCurrencySymbolForCountry(customCountry || carrierForm.country || preset.currency);

    setCarrierForm(prev => {
      let updatedCostPerMin = prev.cost_per_min;
      let updatedInboundCost = prev.inbound_cost || `${sym}0.0085`;
      let updatedDidMonthlyCost = prev.did_monthly_cost;
      let updatedBillingInterval = prev.billing_interval || '60s/60s (Standard)';
      let updatedTrialCredits = prev.trial_credits || `${sym}15.00`;
      let updatedTrialMinutes = prev.trial_minutes || '500 mins';
      let updatedFlatRate = prev.flat_monthly_rate || (sym === '₹' ? '₹2,999 / mo' : '$49.00 / mo');
      let updatedTier1 = prev.custom_tier1_rate || `${sym}0.010 / min`;
      let updatedTier2 = prev.custom_tier2_rate || `${sym}0.007 / min`;
      let updatedCommit = prev.min_monthly_commit || `${sym}250.00`;

      if (norm === 'Paid') {
        if (currPresetKey === 'exotel' || currPresetKey === 'knowlarity' || currPresetKey === 'tata_smartflo' || currPresetKey === 'airtel_iq' || currPresetKey === 'jio_enterprise' || currPresetKey === 'myoperator' || currPresetKey === 'servetel' || sym === '₹') {
          updatedCostPerMin = currPresetKey === 'knowlarity' ? '₹0.85' : currPresetKey === 'tata_smartflo' ? '₹0.65' : currPresetKey === 'airtel_iq' ? '₹0.60' : currPresetKey === 'jio_enterprise' ? '₹0.55' : '₹0.70';
          updatedInboundCost = '₹0.40';
          updatedDidMonthlyCost = currPresetKey === 'knowlarity' ? '₹750.00' : '₹500.00';
        } else if (currPresetKey === 'telnyx') {
          updatedCostPerMin = '$0.007';
          updatedInboundCost = '$0.005';
          updatedDidMonthlyCost = '$0.85';
        } else if (currPresetKey === 'plivo') {
          updatedCostPerMin = '$0.012';
          updatedInboundCost = '$0.0075';
          updatedDidMonthlyCost = '$0.80';
        } else if (currPresetKey === 'vonage') {
          updatedCostPerMin = '$0.013';
          updatedInboundCost = '$0.008';
          updatedDidMonthlyCost = '$0.90';
        } else if (currPresetKey === 'sinch') {
          updatedCostPerMin = '$0.011';
          updatedInboundCost = '$0.007';
          updatedDidMonthlyCost = '$0.85';
        } else if (currPresetKey === 'bandwidth') {
          updatedCostPerMin = '$0.009';
          updatedInboundCost = '$0.006';
          updatedDidMonthlyCost = '$0.50';
        } else if (currPresetKey === 'signalwire') {
          updatedCostPerMin = '$0.0095';
          updatedInboundCost = '$0.0055';
          updatedDidMonthlyCost = '$0.70';
        } else if (currPresetKey === 'aws_chime') {
          updatedCostPerMin = '$0.0035';
          updatedInboundCost = '$0.0022';
          updatedDidMonthlyCost = '$1.00';
        } else if (currPresetKey === 'azure_acs') {
          updatedCostPerMin = '$0.004';
          updatedInboundCost = '$0.003';
          updatedDidMonthlyCost = '$1.00';
        } else {
          updatedCostPerMin = `${sym}0.014`;
          updatedInboundCost = `${sym}0.0085`;
          updatedDidMonthlyCost = `${sym}1.00`;
        }
        updatedBillingInterval = currPresetKey === 'telnyx' || currPresetKey === 'aws_chime' || currPresetKey === 'azure_acs' ? '1s/1s (Per-Second)' : '60s/60s (Standard)';
      } else if (norm === 'Free') {
        updatedCostPerMin = `${sym}0.00 / min (Free)`;
        updatedInboundCost = `${sym}0.00 / min (Free)`;
        updatedDidMonthlyCost = `${sym}0.00 (Zero Charge)`;
        updatedBillingInterval = 'Zero Platform Charge (Pass-Through)';
      } else if (norm === 'Free Trial') {
        updatedCostPerMin = `${sym}0.00 (Trial Active)`;
        updatedInboundCost = `${sym}0.00 (Trial Active)`;
        updatedDidMonthlyCost = `${sym}0.00 (Included in Trial)`;
        updatedTrialCredits = sym === '₹' ? '₹1,000.00' : '$15.00';
        updatedTrialMinutes = '500 mins';
        updatedBillingInterval = 'Trial Sandbox Mode';
      } else if (norm === 'Flat-Rate Unlimited') {
        updatedCostPerMin = `${sym}0.00 (Unlimited Bundle)`;
        updatedInboundCost = `${sym}0.00 (Unlimited Bundle)`;
        updatedDidMonthlyCost = `${sym}0.00 (Included in Bundle)`;
        updatedFlatRate = sym === '₹' ? '₹2,999 / mo' : '$49.00 / mo';
        updatedBillingInterval = 'Monthly Unlimited Subscription';
      } else if (norm === 'Custom') {
        updatedCostPerMin = `${sym}0.010`;
        updatedInboundCost = `${sym}0.005`;
        updatedDidMonthlyCost = `${sym}1.00`;
        updatedTier1 = `${sym}0.010 / min (<10k mins)`;
        updatedTier2 = `${sym}0.007 / min (>50k mins)`;
        updatedCommit = sym === '₹' ? '₹15,000.00' : '$250.00';
        updatedBillingInterval = 'Negotiated Enterprise Rate Card';
      }

      return {
        ...prev,
        pricing_mode: norm,
        cost_per_min: updatedCostPerMin,
        inbound_cost: updatedInboundCost,
        did_monthly_cost: updatedDidMonthlyCost,
        billing_interval: updatedBillingInterval,
        trial_credits: updatedTrialCredits,
        trial_minutes: updatedTrialMinutes,
        flat_monthly_rate: updatedFlatRate,
        custom_tier1_rate: updatedTier1,
        custom_tier2_rate: updatedTier2,
        min_monthly_commit: updatedCommit
      };
    });
  };

  const applyCarrierPreset = (presetKey: CarrierPresetKey) => {
    setCarrierPreset(presetKey);
    const preset = TELEPHONY_CARRIER_PRESETS[presetKey];
    if (!preset) return;
    const defaultMode = preset.pricing_mode || (preset.authType === 'gsm_gateway' ? 'Free' : 'Paid');
    const sym = getCurrencySymbolForCountry(preset.country || preset.currency);

    setCarrierForm(prev => {
      const isGenericName = !prev.name || Object.values(TELEPHONY_CARRIER_PRESETS).some(p => p.defaultName === prev.name || p.name === prev.name);
      return {
        ...prev,
        preset_key: presetKey,
        name: isGenericName ? preset.defaultName : prev.name,
        provider_type: preset.provider_type,
        country: preset.country,
        currency: preset.currency,
        pricing_mode: defaultMode,
        cost_per_min: preset.cost_per_min,
        inbound_cost: preset.inbound_cost || `${sym}0.008`,
        did_monthly_cost: preset.did_monthly_cost,
        billing_interval: preset.billing_interval || '60s/60s (Standard)',
        flat_monthly_rate: preset.flat_monthly_rate || (sym === '₹' ? '₹2,999 / mo' : '$49.00 / mo'),
        trial_credits: preset.trial_credits || (sym === '₹' ? '₹1,000.00' : '$15.00'),
        base_url: preset.base_url,
        webhook_url: preset.webhook_url,
        description: prev.description && !Object.values(TELEPHONY_CARRIER_PRESETS).some(p => p.description === prev.description) ? prev.description : preset.description
      };
    });
  };

