  const handleProviderCategoryChange = (newCategory: string) => {
    let defaultPresetForCategory: CarrierPresetKey = 'twilio';
    if (newCategory === 'DID Provider') defaultPresetForCategory = 'exotel';
    else if (newCategory === 'SIP Carrier') defaultPresetForCategory = 'telnyx';
    else if (newCategory === 'Local/Custom Carrier') defaultPresetForCategory = 'freepbx';
    else if (newCategory === 'GSM Carrier') defaultPresetForCategory = 'gsm';
    else if (newCategory === 'Custom') defaultPresetForCategory = 'custom';
    else if (newCategory === 'Cloud Telephony') defaultPresetForCategory = 'twilio';
    else if (newCategory === 'all') defaultPresetForCategory = carrierPreset;

    setCarrierForm(prev => ({
      ...prev,
      provider_type: newCategory === 'all' ? 'All Categories' : newCategory
    }));

    if (newCategory !== 'all') {
      applyCarrierPreset(defaultPresetForCategory);
    }
  };

