      canonicalType = 'Industrial GSM Router';
      if (!keepExistingValues || !gsmForm.name) suggestedName = 'Teltonika RUT955 Industrial GSM Router';
      if (!keepExistingValues || !gsmForm.ip_host) suggestedIp = '192.168.1.170:8080';
      suggestedProtocol = 'MQTT / Modbus Telemetry';
