  // Helper to dynamically get SelectOption[] for all live models of a given provider (matches Tab 1 SSOT format)
  const getDynamicModelOptionsForProvider = useCallback((provNameOrKey: string): SelectOption[] => {
    const raw = typeof provNameOrKey === 'string' ? provNameOrKey.toLowerCase().trim() : '';

    // Find matching connected credential from Tab 1
    const matchingCred = (credentials || []).find((c: any) => {
      const p = typeof (c?.provider || c?.provider_name || c?.name) === 'string' ? (c.provider || c.provider_name || c.name).toLowerCase().trim() : '';
      const disp = typeof (c?.name || c?.display_name) === 'string' ? (c.name || c.display_name).toLowerCase().trim() : '';
      return (p && (p === raw || disp === raw || raw.includes(p) || p.includes(raw))) || false;
    });

    const fallbackKey = raw.includes('google') || raw.includes('gemini') ? 'google' :
      raw.includes('anthropic') || raw.includes('claude') ? 'anthropic' :
      raw.includes('ollama') ? 'ollama' :
      raw.includes('openai') || raw.includes('gpt') ? 'openai' :
      raw.includes('groq') ? 'groq' : (raw || 'google');

    const pKey = typeof (matchingCred?.provider || matchingCred?.provider_name) === 'string'
      ? (matchingCred.provider || matchingCred.provider_name).toLowerCase()
      : fallbackKey;

    const cacheEntry = (modelsCache && modelsCache[pKey]) ? modelsCache[pKey] :
      (pKey === 'google' ? (modelsCache?.['google'] || modelsCache?.['gemini'] || modelsCache?.['google_ai_studio']) : null) ||
      (pKey === 'anthropic' ? (modelsCache?.['anthropic'] || modelsCache?.['claude']) : null) ||
      (pKey === 'ollama' ? modelsCache?.['ollama'] : null) ||
      (pKey === 'openai' ? modelsCache?.['openai'] : null) ||
      (pKey === 'groq' ? modelsCache?.['groq'] : null);

    const opts: SelectOption[] = [];
    const seen = new Set<string>();

    if (Array.isArray(cacheEntry) && cacheEntry.length > 0) {
      cacheEntry.forEach((m: any) => {
        const id = typeof m === 'string' ? m : (m?.id || m?.name || m?.model || String(m || ''));
        const label = typeof m === 'string' ? m : (m?.display_name || m?.label || m?.name || m?.id || String(m || ''));
        if (id && !seen.has(id)) {
          seen.add(id);
          opts.push({
            value: id,
            label: `🔒 Fixed Model: ${label}`,
            description: `Live Dynamic Model (${pKey.toUpperCase()} SSOT API)`,
            group: `${matchingCred?.name || pKey.toUpperCase()} Live Models (${cacheEntry.length} Models)`
          });
        }
      });
    } else if (matchingCred && matchingCred.primary_model && !['dynamic', 'default'].includes(matchingCred.primary_model)) {
      const prim = matchingCred.primary_model;
      seen.add(prim);
      opts.push({
        value: prim,
        label: `🔒 Fixed Model: ${prim}`,
        description: `Configured Model from Tab 1 SSOT`,
        group: `${matchingCred.name || pKey.toUpperCase()} Configured Model`
      });
    }

    // Default fallback models only if live API response is still pending
    if (opts.length === 0) {
      if (pKey === 'google' || raw.includes('google') || raw.includes('gemini')) {
        [
          { id: 'gemini-3.6-flash', label: 'Gemini 3.6 Flash', desc: 'Active SSOT Model' },
          { id: 'gemini-2.5-flash', label: 'Gemini 2.5 Flash', desc: 'Ultra low latency' },
          { id: 'gemini-2.5-pro', label: 'Gemini 2.5 Pro', desc: 'Complex reasoning' },
          { id: 'gemini-1.5-flash', label: 'Gemini 1.5 Flash', desc: 'Production voice model' },
          { id: 'gemini-1.5-pro', label: 'Gemini 1.5 Pro', desc: 'Deep contextual reasoning' }
        ].forEach(m => {
          opts.push({
            value: m.id,
            label: `🔒 Fixed Model: ${m.label}`,
            description: m.desc,
            group: 'Google AI Studio Models'
          });
        });
      } else if (pKey === 'anthropic' || raw.includes('anthropic') || raw.includes('claude')) {
        [
          { id: 'claude-3-5-sonnet-20241022', label: 'Claude 3.5 Sonnet', desc: 'High intelligence & natural tone' },
          { id: 'claude-3-5-haiku-20241022', label: 'Claude 3.5 Haiku', desc: 'Fast conversational response' },
          { id: 'claude-3-opus-20240229', label: 'Claude 3 Opus', desc: 'Complex analysis' }
        ].forEach(m => {
          opts.push({
            value: m.id,
            label: `🔒 Fixed Model: ${m.label}`,
            description: m.desc,
            group: 'Anthropic Claude Models'
          });
        });
      } else if (pKey === 'ollama' || raw.includes('ollama')) {
        [
          { id: 'llama3:latest', label: 'Llama 3 (Local)', desc: 'Local self-hosted engine' },
          { id: 'mistral:latest', label: 'Mistral 7B (Local)', desc: 'Local fast inference' },
          { id: 'qwen2.5:latest', label: 'Qwen 2.5 (Local)', desc: 'Local multilingual model' }
        ].forEach(m => {
          opts.push({
            value: m.id,
            label: `🔒 Fixed Model: ${m.label}`,
            description: m.desc,
            group: 'Ollama Local Models'
          });
        });
      }
    }

    return opts;
  }, [credentials, modelsCache]);



