  const handleDeleteRecordWithDependencyCheck = async (item: any) => {
    setIsCheckingDependency(true);
    setDependencyTarget(item);
    try {
      const credId = item.id || item.provider || item.name;
      const token = getAuthToken();
      const headers: Record<string, string> = {};
      if (token) headers['Authorization'] = `Bearer ${token}`;

      const res = await fetch(`/api/credentials/${encodeURIComponent(credId)}/dependencies`, { headers });
      if (res.ok) {
        const data = await res.json();
        setDependencyInfo(data);
        if (data.is_referenced) {
          setIsDependencyModalOpen(true);
          return;
        }
      }
    } catch (e) {
      console.error('Dependency check error', e);
    } finally {
      setIsCheckingDependency(false);
    }
    setDeleteTarget(item);
  };

