  const copyToClipboard = (text: string): boolean => {
    if (!text) return false;
    try {
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text);
        return true;
      }
    } catch (e) {
      // Fallback to execCommand below
    }
    try {
      const textarea = document.createElement('textarea');
      textarea.value = text;
      textarea.style.position = 'fixed';
      textarea.style.left = '-999999px';
      textarea.style.top = '-999999px';
      textarea.setAttribute('readonly', '');
      document.body.appendChild(textarea);
      textarea.focus();
      textarea.select();
      const successful = document.execCommand('copy');
      document.body.removeChild(textarea);
      return successful;
    } catch (err) {
      console.error('Copy fallback error:', err);
      return false;
    }
  };

  const persistRecordToBackend = async (newItem: any, categoryKey: string) => {
    const token = getAuthToken();
    const headers: Record<string, string> = { 'Content-Type': 'application/json' };
    if (token) headers['Authorization'] = `Bearer ${token}`;

    if (categoryKey === 'webhooks') {
      const whRes = await fetch('/api/webhooks', {
        method: 'POST',
        headers,
        body: JSON.stringify({
          name: newItem.name || 'webhook_endpoint',
          display_name: newItem.display_name || newItem.name,
          description: newItem.description || '',
          endpoint_url: newItem.url || newItem.webhook_url || newItem.endpoint_url || 'https://httpbin.org/post',
          http_method: newItem.http_method || 'POST',
          auth_type: newItem.auth_type || 'HMAC Signature',
          auth_secret: newItem.auth_secret || newItem.auth_token || '',
          subscribed_events: newItem.subscribed_events || ['call.completed'],
          timeout_seconds: parseInt(String(newItem.timeout || '10').replace('s', ''), 10) || 10,
          max_retries: parseInt(String(newItem.max_retries || '3'), 10) || 3,
          retry_backoff: newItem.retry_backoff || 'Exponential (2s / 4s / 8s)',
          verify_ssl: newItem.verify_ssl !== false,
          custom_headers: newItem.custom_headers || [],
          status: newItem.status || 'Active',
          scope: newItem.scope || 'Global Workspace',
        })
      });
      if (!whRes.ok) {
        const errorData = await whRes.json().catch(() => ({}));
        throw new Error(errorData.detail || errorData.message || `HTTP ${whRes.status} Error saving webhook`);
      }
      return true;
    }

    const res = await fetch('/api/credentials/', {
      method: 'POST',
      headers,
      body: JSON.stringify({
        id: newItem.id,
        provider: (newItem.name || newItem.display_name || categoryKey).toLowerCase().replace(/\s+/g, '_'),
        display_name: newItem.display_name || newItem.name || categoryKey,
        category: categoryKey,
        api_key: 'config_rule',
        primary_model: newItem.category || newItem.provider_type || newItem.device_type || newItem.direction || 'custom',
        metadata_json: newItem
      })
    });

    if (!res.ok) {
      const errorData = await res.json().catch(() => ({}));
      const errorDetail = errorData.detail || errorData.message || `HTTP ${res.status} Error saving record`;
      throw new Error(errorDetail);
    }
    return true;
  };

  const fetchData = async (isSilent: boolean = true) => {
    const isReallySilent = typeof isSilent === 'boolean' ? isSilent : true;
    try {
      if (!isReallySilent) setIsLoading(true);
      const token = getAuthToken();
      const headers: Record<string, string> = {};
      if (token) headers['Authorization'] = `Bearer ${token}`;

      const [allCatsRes, credRes, regRes, demoRes, agentsRes, campaignsRes] = await Promise.all([
        fetch('/api/credentials/all-categories', { headers }).catch(() => null),
        fetch('/api/credentials/', { headers }).catch(() => null),
        fetch('/api/providers/', { headers }).catch(() => null),
        fetch('/api/demo/config-options', { headers }).catch(() => null),
        fetch('/api/agents', { headers }).catch(() => null),
        fetch('/api/campaigns', { headers }).catch(() => null)
      ]);

      if (allCatsRes && allCatsRes.ok) {
        const allCatsData = await allCatsRes.json();
        if (allCatsData && typeof allCatsData === 'object') {
          if (allCatsData.llm) setLlmProviders(allCatsData.llm);
          setCustomItems(prev => {
            const newState: Record<string, any[]> = {};
            Object.keys(allCatsData).forEach(cat => {
              newState[cat] = Array.isArray(allCatsData[cat]) ? allCatsData[cat] : [];
            });
            try {
              localStorage.setItem('nexus_custom_items', JSON.stringify(newState));
            } catch (e) {}
            return newState;
          });
        }
      }

      if (credRes && credRes.ok) {
        const data = await credRes.json();
        const loadedCreds = data.credentials || [];
        setCredentials(loadedCreds);

        // Synchronize all DB credentials to customItems so cards immediately reflect accurate clean DB state
        setCustomItems(prev => {
          const nextState: Record<string, any[]> = { ...prev };
          const byCat: Record<string, any[]> = {};
          loadedCreds.forEach((c: any) => {
            const cat = c.category;
            if (cat) {
              if (!byCat[cat]) byCat[cat] = [];
              const meta = c.metadata_json || c.metadata || {};
              byCat[cat].push({
                ...meta,
                id: c.id,
                name: meta.name || c.display_name || c.provider,
                display_name: c.display_name || meta.display_name || c.provider,
                provider: c.provider,
                base_url: c.base_url || meta.base_url || meta.sip_host || meta.ip_host,
                primary_model: c.primary_model || meta.primary_model,
                status: meta.status || 'Active'
              });
            }
          });

          Object.keys(byCat).forEach(cat => {
            if (byCat[cat].length > 0) {
              nextState[cat] = byCat[cat];
            }
          });

          try {
            localStorage.setItem('nexus_custom_items', JSON.stringify(nextState));
          } catch (e) {}
          return nextState;
        });

        // Automatically fetch live models for all connected LLM providers from Tab 1 SSOT
        loadedCreds
          .filter((c: any) => c.category === 'llm' || ['google', 'openai', 'anthropic', 'groq', 'deepseek', 'ollama'].includes((c.provider || c.provider_name || '').toLowerCase()))
          .forEach((c: any) => {
            const pKey = c.provider || c.provider_name;
            if (pKey) {
              handleFetchDynamicModels(pKey, c.base_url, c.raw_key);
            }
          });
      }

      if (regRes && regRes.ok) {
        const data = await regRes.json();
        setRegistry({ llm: data.llm || [], voice: data.voice || [] });
      }

      if (demoRes && demoRes.ok) {
        const demoData = await demoRes.json();
        setGlobalConfigData(demoData);
      }

      if (agentsRes && agentsRes.ok) {
        const agentsData = await agentsRes.json();
        const list = agentsData.items || agentsData.agents || [];
        if (list.length > 0) {
          setWorkspaceAgents(list);
        }
      }

      if (campaignsRes && campaignsRes.ok) {
        const campaignsData = await campaignsRes.json();
        const cList = Array.isArray(campaignsData) ? campaignsData : campaignsData.items || campaignsData.campaigns || [];
        if (cList.length > 0) {
          setWorkspaceCampaigns(cList);
        }
      }
    } catch (e) {
      console.error(e);
      addToast({ type: 'error', title: 'Error Loading Data', description: 'Failed to fetch configuration registry.' });
    } finally {
      setIsLoading(false);
      setHasFetchedCredentials(true);
    }
  };

