      const providerName = (cat?.name || cred.provider || '').toLowerCase();
      const modelId = (cred.default_model_id || '').toLowerCase();
      const query = llmSearchQuery.toLowerCase().trim();

      const matchesSearch = !query || providerName.includes(query) || modelId.includes(query);

      const testRes = testResults[cred.id] || testResults[cred.provider];
      const isConnected = testRes?.status === 'Connected' || !!cred.raw_key || !!cred.base_url;
      const matchesStatus =
        llmStatusFilter === 'all'
          ? true
          : llmStatusFilter === 'connected'
            ? isConnected
            : !isConnected;

      const matchesCategory =
        llmCategoryFilter === 'all'
          ? true
          : llmCategoryFilter === 'cloud'
