                      const matchingTimeFormat = TIME_FORMAT_OPTIONS.find(t => t.toLowerCase().startsWith(lang.timeFormat.toLowerCase().split(' ')[0])) || lang.timeFormat;
                      setBTimeFormat(matchingTimeFormat);
