                e.preventDefault();
                e.stopPropagation();
                const editId = editingDispositionItem?.id;
                const editName = editingDispositionItem?.name;
                const newItem = {
                  id: editId || ('disp-' + Date.now()),
                  ...dispositionForm,
                  status: dispositionForm.status || 'Active',
                  updatedAt: new Date().toLocaleDateString()
                };
                setCustomItems(prev => {
                  const currentList = prev['dispositions'] || [];
                  const filtered = currentList.filter((i: any) => i.id !== newItem.id && i.id !== editId && i.name !== editName && i.name !== newItem.name);
                  const updated = [newItem, ...filtered];
                  const nextState = { ...prev, dispositions: updated };
                  try { localStorage.setItem('nexus_custom_items', JSON.stringify(nextState)); } catch (err) {}
                  return nextState;
                });
                persistRecordToBackend(newItem, 'dispositions');
                setIsDispositionModalOpen(false);
                setEditingDispositionItem(null);
                addToast({ type: 'success', title: 'Disposition Outcome Active', description: `${newItem.name} registered across CRM & AI agents.` });
